SELECT *, NTILE(4) OVER w_part AS discount_pct_bucket, ROW_NUMBER() OVER w_part_2 AS seq_no, MAX(discount_pct) OVER (PARTITION BY channel) AS channel_max_discount_pct, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY promo_code), 4) AS discount_pct_share FROM promotions WINDOW w_part AS (PARTITION BY channel, promo_code ORDER BY discount_pct DESC, id), w_part_2 AS (ORDER BY ends_on DESC, id)
